namespace JdHelper {
 public static class SelfTests {
  class Fake:ILookup { public Func<string,Receiver> Fn;public int Calls;public Receiver Query(string w){Calls++;return Fn(w);} }
  static void Assert(bool value,string message){if(!value)throw new Exception("TEST FAILED: "+message);}
  static bool Kept(string path){return File.Exists(path+".京东查单记录.json")&&File.Exists(path+".京东查单运行锁");}
  static bool Cleaned(string path){return !File.Exists(path+".京东查单记录.json")&&!File.Exists(path+".京东查单运行锁");}
  static Receiver R(string bill){return new Receiver{Name="测试人",Phone="13800000000",Address="测试省测试市测试区测试路1号",Waybill=bill};}
  static string Fixture(string folder,string name){
   string p=Path.Combine(folder,name+".xlsx");
   using(var zip=ZipFile.Open(p,ZipArchiveMode.Create)){
    Add(zip,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"xml\" ContentType=\"application/xml\"/></Types>");
    Add(zip,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Sheet1\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
    Add(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Target=\"worksheets/sheet1.xml\"/></Relationships>");
    Add(zip,"xl/worksheets/sheet1.xml","<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData><row r=\"1\"><c r=\"F1\" t=\"inlineStr\"><is><t>单号</t></is></c></row><row r=\"2\"><c r=\"B2\" s=\"1\" t=\"inlineStr\"><is><t>测**</t></is></c><c r=\"C2\" t=\"inlineStr\"><is><t>1********00</t></is></c><c r=\"F2\" t=\"inlineStr\"><is><t>JDVA00000000001</t></is></c></row><row r=\"3\"><c r=\"F3\" t=\"inlineStr\"><is><t>JDVA00000000002</t></is></c></row></sheetData></worksheet>");
    Add(zip,"unchanged.bin","unchanged-content-123");
   }return p;
  }
  static void Add(ZipArchive z,string name,string text){using(var w=new StreamWriter(z.CreateEntry(name).Open(),new UTF8Encoding(false)))w.Write(text);}
  static string Entry(string file,string name){using(var z=ZipFile.OpenRead(file))using(var r=new StreamReader(z.GetEntry(name).Open()))return r.ReadToEnd();}
  public static object Run(string root){
   string folder=Path.Combine(root,"selftest-"+DateTime.Now.ToString("yyyyMMddHHmmss"));Directory.CreateDirectory(folder);var passed=new List<string>();
   string p=Fixture(folder,"write");var b=new WorkbookStore(p,"Sheet1");var order=b.LoadRows()[0];string before=Entry(p,"unchanged.bin");b.Write(order,R(order.Waybill));Assert(b.LoadRows()[0].Complete,"write/read");Assert(Entry(p,"unchanged.bin")==before,"unrelated ZIP entry");Assert(Entry(p,"xl/worksheets/sheet1.xml").Contains("s=\"1\""),"style");passed.Add("write/read, unrelated entries and styles preserved");
   string hash=WorkbookStore.Hash(File.ReadAllBytes(p));bool blocked=false;try{var wrong=R("JDVA00000000009");b.Write(order,wrong);}catch{blocked=true;}Assert(blocked&&hash==WorkbookStore.Hash(File.ReadAllBytes(p)),"wrong waybill blocked");passed.Add("wrong waybill cannot write");
   p=Fixture(folder,"mismatch");b=new WorkbookStore(p,"Sheet1");order=b.LoadRows()[0];blocked=false;try{var wrong=R(order.Waybill);wrong.Name="另一人";b.Write(order,wrong);}catch{blocked=true;}Assert(blocked&&!b.LoadRows()[0].Complete,"mask mismatch blocked");passed.Add("masked name mismatch blocked");
   p=Fixture(folder,"external");b=new WorkbookStore(p,"Sheet1");order=b.LoadRows()[0];using(var z=ZipFile.Open(p,ZipArchiveMode.Update))Add(z,"external.txt","changed");blocked=false;try{b.Write(order,R(order.Waybill));}catch(FatalError){blocked=true;}Assert(blocked,"external change detected");passed.Add("external modification stops write");
   p=Fixture(folder,"retry");int n=0;var f=new Fake{Fn=w=>{if(++n==1)throw new Exception("transient");return R(w);}};var sum=new BatchRunner().Run(p,"Sheet1",1,2,f,new RunControl());Assert(sum.Completed==1&&f.Calls==2,"transient retry");Assert(Kept(p)&&!sum.AllComplete&&sum.Remaining==1,"batch limit must retain checkpoint and lock");passed.Add("transient failure retries successfully; partial batch retains both files");
   p=Fixture(folder,"invalid");f=new Fake{Fn=w=>{if(w.EndsWith("01"))throw new NoWaybill();return R(w);}};sum=new BatchRunner().Run(p,"Sheet1",0,1,f,new RunControl());Assert(sum.Failed==1&&sum.Completed==1&&f.Calls==2,"invalid then continue without retrying definitive failure");Assert(Kept(p)&&!sum.AllComplete,"failure must retain both files");passed.Add("no-waybill is marked without extra retries; next row still completes");
   Assert(new WorkbookStore(p,"Sheet1").LoadRows()[0].Unreadable&&sum.Unreadable==1&&sum.Pending==0,"unreadable counts");
   File.Delete(p+".京东查单记录.json");f=new Fake{Fn=w=>{throw new Exception("must skip unreadable");}};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(f.Calls==0&&sum.SkippedUnreadable==1&&sum.Skipped==1&&Kept(p)&&!sum.AllComplete,"marker survives loss of ledger");passed.Add("default restart skips unreadable orders even with checkpoint removed");
   string xmlBeforeRetry=Entry(p,"xl/worksheets/sheet1.xml"),stylesBeforeRetry=Entry(p,"xl/styles.xml");
   f=new Fake{Fn=w=>R(w)};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl(),true);Assert(f.Calls==1&&sum.Completed==1&&sum.AllComplete&&Cleaned(p)&&!new WorkbookStore(p,"Sheet1").LoadRows()[0].Unreadable,"explicit retry clears marker");Assert(Entry(p,"xl/styles.xml")==stylesBeforeRetry,"successful retry preserves original styles and conditional formatting");passed.Add("explicit recheck clears failure marker, restores conditional colors and allows cleanup");
   p=Fixture(folder,"mark-identity");b=new WorkbookStore(p,"Sheet1");order=b.LoadRows()[0];b.MarkUnreadable(order,"运单已取消");string stylesOnce=Entry(p,"xl/styles.xml");b.MarkUnreadable(order,"仍不可读");Assert(Entry(p,"xl/styles.xml")==stylesOnce&&Entry(p,"unchanged.bin")==before,"repeated marking does not duplicate styles or change unrelated entries");
   XNamespace ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
   using(var z=ZipFile.Open(p,ZipArchiveMode.Update)){var doc=XDocument.Parse(EntryText(z,"xl/worksheets/sheet1.xml"));var cell=doc.Descendants(ns+"c").Single(x=>(string)x.Attribute("r")=="F2");cell.Descendants(ns+"t").Single().Value="JDVA00000000009";z.GetEntry("xl/worksheets/sheet1.xml").Delete();Add(z,"xl/worksheets/sheet1.xml",doc.ToString());}
   Assert(!new WorkbookStore(p,"Sheet1").LoadRows()[0].Unreadable,"edited waybill cannot inherit unreadable marker");passed.Add("marker is tied to exact waybill; changing the number makes it eligible again");
   p=Fixture(folder,"mark-layout");using(var z=ZipFile.Open(p,ZipArchiveMode.Update)){var doc=XDocument.Parse(EntryText(z,"xl/worksheets/sheet1.xml"));doc.Descendants(ns+"row").First().Add(new XElement(ns+"c",new XAttribute("r","J1"),new XAttribute("t","inlineStr"),new XElement(ns+"is",new XElement(ns+"t","已有业务列"))));doc.Descendants(ns+"row").Last().Add(new XElement(ns+"c",new XAttribute("r","J3"),new XElement(ns+"f","1+2"),new XElement(ns+"v",3)));z.GetEntry("xl/worksheets/sheet1.xml").Delete();Add(z,"xl/worksheets/sheet1.xml",doc.ToString());}
   b=new WorkbookStore(p,"Sheet1");b.MarkUnreadable(b.LoadRows()[0],"测试缺少存根");var markedDoc=XDocument.Parse(Entry(p,"xl/worksheets/sheet1.xml"));Assert(markedDoc.Descendants(ns+"c").Any(x=>(string)x.Attribute("r")=="K1")&&markedDoc.Descendants(ns+"f").Single().Value=="1+2"&&markedDoc.Descendants(ns+"conditionalFormatting").Any(),"status is appended after occupied columns");passed.Add("status column appends after existing business data; formulas and unrelated entries stay intact");
   p=Fixture(folder,"retry-exhausted");f=new Fake{Fn=w=>{throw new Exception("temporary but persistent");}};sum=new BatchRunner().Run(p,"Sheet1",0,3,f,new RunControl());Assert(f.Calls==8&&sum.Failed==2&&sum.Error==null&&sum.Unreadable==2,"retry allowance is per order");f=new Fake{Fn=w=>{throw new Exception("default rerun should not query");}};sum=new BatchRunner().Run(p,"Sheet1",0,3,f,new RunControl());Assert(f.Calls==0&&sum.SkippedUnreadable==2,"exhausted retry markers skipped");passed.Add("each failed order receives its own retry budget; exhausted orders are skipped on restart");
   p=Fixture(folder,"mark-external");b=new WorkbookStore(p,"Sheet1");order=b.LoadRows()[0];using(var z=ZipFile.Open(p,ZipArchiveMode.Update))Add(z,"external.txt","change");blocked=false;try{b.MarkUnreadable(order,"failure");}catch(FatalError){blocked=true;}Assert(blocked&&!new WorkbookStore(p,"Sheet1").LoadRows()[0].Unreadable,"external modification blocks marking");passed.Add("failure marking detects external changes before replacing the workbook");
   p=Fixture(folder,"resume");FileStream held=null;f=new Fake{Fn=w=>{held=new FileStream(p,FileMode.Open,FileAccess.ReadWrite,FileShare.None);return R(w);}};
   sum=new BatchRunner().Run(p,"Sheet1",1,0,f,new RunControl());held.Dispose();Assert(sum.Error!=null&&Kept(p),"locked file stops and retains both files");
   f=new Fake{Fn=w=>{throw new Exception("must reuse pending result");}};sum=new BatchRunner().Run(p,"Sheet1",1,0,f,new RunControl());Assert(sum.Completed==1&&f.Calls==0,"resume cached result");passed.Add("file lock stops safely; pending result resumes without querying");
   f=new Fake{Fn=w=>R(w)};sum=new BatchRunner().Run(p,"Sheet1",1,0,f,new RunControl());Assert(sum.Completed==1&&sum.Skipped==1&&f.Calls==1,"completed skipped");passed.Add("completed records skipped on resume");
   p=Fixture(folder,"stop");var c=new RunControl();f=new Fake{Fn=w=>{c.RequestStop("测试停止按钮");return R(w);}};sum=new BatchRunner().Run(p,"Sheet1",1,0,f,c);Assert(sum.Stopped&&Kept(p)&&!new WorkbookStore(p,"Sheet1").LoadRows()[0].Complete,"stop before write");var stoppedLedger=Json.Decode<Ledger>(File.ReadAllText(p+".京东查单记录.json",Encoding.UTF8));Assert(sum.StopReason=="测试停止按钮"&&stoppedLedger.LastStopReason==sum.StopReason&&stoppedLedger.LastRunStatus=="已停止","stop source persists");passed.Add("stop reason is preserved in summary and checkpoint");f=new Fake{Fn=w=>{throw new Exception("should not query");}};sum=new BatchRunner().Run(p,"Sheet1",1,0,f,new RunControl());Assert(sum.Completed==1&&f.Calls==0,"resume stop");passed.Add("stop before write preserves both files and pending result for resume");
   p=Fixture(folder,"cleanup-full");f=new Fake{Fn=w=>R(w)};sum=new BatchRunner().Run(p,"Sheet1",2,0,f,new RunControl());Assert(sum.AllComplete&&sum.AuxFilesCleaned&&sum.Remaining==0&&Cleaned(p),"full sheet must clean both files even with exact batch limit");Assert(File.Exists(p)&&File.Exists(sum.Backup)&&new WorkbookStore(p,"Sheet1").LoadRows().All(r=>r.Complete),"workbook and backup remain intact");passed.Add("full sheet removes both auxiliary files, preserves workbook and backup");
   f=new Fake{Fn=w=>{throw new Exception("already complete should not query");}};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(sum.AllComplete&&sum.AuxFilesCleaned&&sum.Skipped==2&&f.Calls==0&&Cleaned(p),"already complete rerun cleanup");passed.Add("already complete sheet can run again and clean both files without querying");
   p=Fixture(folder,"cleanup-late-stop");c=new RunControl();f=new Fake{Fn=w=>R(w)};var runner=new BatchRunner{Log=s=>{if(s.StartsWith("第 3 行")&&s.Contains("已核对并写入"))c.RequestStop("测试末行停止");}};sum=runner.Run(p,"Sheet1",0,0,f,c);Assert(sum.Stopped&&sum.Completed==2&&Kept(p),"stop after last write must still retain both files");f=new Fake{Fn=w=>{throw new Exception("must not requery completed rows");}};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(sum.AuxFilesCleaned&&Cleaned(p)&&f.Calls==0,"resume after late stop cleans safely");passed.Add("manual stop after last write retains both files; normal resume cleans them");
   p=Fixture(folder,"cleanup-retried");n=0;f=new Fake{Fn=w=>{if(++n==1)throw new Exception("transient");return R(w);}};sum=new BatchRunner().Run(p,"Sheet1",0,1,f,new RunControl());Assert(sum.Completed==2&&sum.Failed==0&&sum.AuxFilesCleaned&&Cleaned(p),"recovered temporary failure allows full cleanup");passed.Add("successful retry followed by full completion allows cleanup");
   p=Fixture(folder,"cleanup-blocked");held=null;f=new Fake{Fn=w=>R(w)};runner=new BatchRunner{Log=s=>{if(s.StartsWith("第 3 行")&&s.Contains("已核对并写入"))held=new FileStream(p+".京东查单记录.json",FileMode.Open,FileAccess.Read,FileShare.Read);}};
   try{sum=runner.Run(p,"Sheet1",0,0,f,new RunControl());Assert(sum.AllComplete&&!sum.AuxFilesCleaned&&sum.CleanupWarning!=null&&Kept(p),"locked checkpoint must report cleanup failure and keep files");}finally{if(held!=null)held.Dispose();}
   f=new Fake{Fn=w=>R(w)};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(sum.AuxFilesCleaned&&Cleaned(p)&&f.Calls==0,"cleanup retries after file unlocked");passed.Add("blocked cleanup reports warning; next run cleans after release");
   p=Fixture(folder,"cleanup-fatal");f=new Fake{Fn=w=>{throw new FatalError("test fatal error");}};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(sum.Error!=null&&!sum.AuxFilesCleaned&&Kept(p),"fatal error must retain both files");passed.Add("fatal error retains both auxiliary files");
   p=Fixture(folder,"cleanup-empty");using(var z=ZipFile.Open(p,ZipArchiveMode.Update)){z.GetEntry("xl/worksheets/sheet1.xml").Delete();Add(z,"xl/worksheets/sheet1.xml","<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData/></worksheet>");}f=new Fake{Fn=w=>R(w)};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());Assert(!sum.AllComplete&&Kept(p)&&f.Calls==0,"empty sheet must not be treated as completed batch");passed.Add("empty sheet is not falsely treated as full completion");
   c=new RunControl();c.Paused=true;Assert(c.RequestStop("快捷键 Ctrl+Alt+F9")&&!c.RequestStop("第二个请求")&&!c.Paused,"first stop reason wins");bool sawReason=false;try{c.Check();}catch(StopRequested e){sawReason=e.Message=="快捷键 Ctrl+Alt+F9";}Assert(sawReason,"stop exception retains source");passed.Add("stop request unpauses safely and preserves its first source");
   Assert(!Hotkeys.IsStop(9,0x78L<<16)&&!Hotkeys.IsStop(9,(0x78L<<16)|1)&&!Hotkeys.IsStop(9,(0x78L<<16)|2)&&Hotkeys.IsStop(9,(0x78L<<16)|3)&&!Hotkeys.IsStop(8,(0x78L<<16)|3)&&Hotkeys.IsPause(8,0x77L<<16),"hotkey modifiers");passed.Add("F9 alone is ignored; only Ctrl+Alt+F9 triggers the stop hotkey");
   p=Fixture(folder,"blank-errors");f=new Fake{Fn=w=>{throw new System.Runtime.InteropServices.COMException("",unchecked((int)0x80040201));}};sum=new BatchRunner().Run(p,"Sheet1",0,0,f,new RunControl());var errorLedger=Json.Decode<Ledger>(File.ReadAllText(p+".京东查单记录.json",Encoding.UTF8));Assert(sum.Failed==2&&!sum.Stopped&&sum.Error==null&&Kept(p)&&errorLedger.Records.Values.All(r=>r.Error.Contains("COMException")&&r.Error.Contains("80040201")),"blank errors must retain type and code without becoming stop requests");passed.Add("blank COM errors retain type and code; two failed orders do not stop the batch");
   string logPath=Diagnostics.NewRunLog(Path.Combine(folder,"logs"));Diagnostics.AppendLog(logPath,"收到停止请求，来源：快捷键 Ctrl+Alt+F9");Assert(File.ReadAllText(logPath,Encoding.UTF8).Contains("来源：快捷键 Ctrl+Alt+F9"),"persistent run log");passed.Add("run log remains readable with stop source after closing");
   int reads=0;int recovered=UiRecovery.Read(()=>{if(++reads<3)throw new System.Windows.Automation.ElementNotAvailableException("");return 42;},new RunControl(),delegate{});Assert(recovered==42&&reads==3,"stale UI elements must be reacquired");passed.Add("transient unavailable UI elements recover by reading fresh controls");
   reads=0;bool bounded=false;try{UiRecovery.Read<int>(()=>{reads++;throw new System.Windows.Automation.ElementNotAvailableException("");},new RunControl(),delegate{});}catch(Exception e){bounded=e.InnerException is System.Windows.Automation.ElementNotAvailableException&&e.Message.Contains("连续刷新");}Assert(bounded&&reads==4,"stale recovery must be bounded");passed.Add("persistent UI refresh has a bounded retry and a readable error");
   reads=0;c=new RunControl();c.RequestStop("测试恢复期间停止");sawReason=false;try{UiRecovery.Read(()=>{reads++;return 1;},c,delegate{});}catch(StopRequested e){sawReason=e.Message==c.StopReason;}Assert(sawReason&&reads==0,"UI recovery must not swallow stop requests");passed.Add("UI refresh recovery honors explicit stop requests");
   long clock=0;int clicks=0;bool revealed=false;
   ClickFeedback.Run(()=>revealed,x=>x,x=>!x,x=>{clicks++;if(clicks==3)revealed=true;},new RunControl(),delegate{},"eye",15000,1800,6,()=>clock,ms=>clock+=ms);
   Assert(clicks==3&&clock>=3600&&clock<5000,"unresponsive eye retries at controlled intervals");passed.Add("unresponsive eye is reacquired and retried until phone reveals");
   clock=0;clicks=0;long responseAt=Int64.MaxValue;
   ClickFeedback.Run(()=>clock>=responseAt,x=>x,x=>!x,x=>{clicks++;responseAt=clock+1600;},new RunControl(),delegate{},"eye",15000,1800,6,()=>clock,ms=>clock+=ms);
   Assert(clicks==1&&clock==1600,"slow network response must not trigger duplicate toggle");passed.Add("delayed reveal is polled immediately; no second click after success");
   reads=0;clicks=0;clock=0;
   ClickFeedback.Run(()=>++reads>=2,x=>x,x=>!x,x=>clicks++,new RunControl(),delegate{},"eye",15000,1800,6,()=>clock,ms=>clock+=ms);
   Assert(clicks==0,"reveal between poll and click must cancel click");passed.Add("fresh check immediately before clicking prevents toggling an already visible phone");
   clock=0;clicks=0;bounded=false;
   try{ClickFeedback.Run(()=>false,x=>x,x=>!x,x=>clicks++,new RunControl(),delegate{},"eye",15000,1800,6,()=>clock,ms=>clock+=ms);}catch(Exception e){bounded=e.Message.Contains("15 秒");}
   Assert(bounded&&clicks==6&&clock==15000,"eye retries bounded");passed.Add("unresponsive phone has bounded time and click count, not an infinite loop");
   clock=0;clicks=0;c=new RunControl();sawReason=false;
   try{ClickFeedback.Run(()=>false,x=>x,x=>!x,x=>{clicks++;c.RequestStop("feedback stop");},c,delegate{},"eye",15000,1800,6,()=>clock,ms=>clock+=ms);}catch(StopRequested e){sawReason=e.Message=="feedback stop";}
   Assert(sawReason&&clicks==1,"stop during feedback loop");passed.Add("feedback retries respect stop requests without further clicks");
   clock=0;clicks=0;int page=0;
   ClickFeedback.Run(()=>page,x=>x==2,x=>x==0,x=>{clicks++;page=1;},new RunControl(),delegate{},"receipt",20000,1800,5,()=>clock,ms=>{clock+=ms;if(clock>=4000)page=2;});
   Assert(clicks==1&&clock==4000,"loading page must not receive another source button click");passed.Add("navigation retries stop clicking once source page changes while awaiting loaded data");
   p=Fixture(folder,"more-than-five-failures");
   using(var z=ZipFile.Open(p,ZipArchiveMode.Update)){
    var doc=XDocument.Parse(EntryText(z,"xl/worksheets/sheet1.xml"));var data=doc.Root.Element(ns+"sheetData");
    for(int index=3;index<=8;index++)data.Add(new XElement(ns+"row",new XAttribute("r",index+1),new XElement(ns+"c",new XAttribute("r","F"+(index+1)),new XAttribute("t","inlineStr"),new XElement(ns+"is",new XElement(ns+"t","JDVA"+index.ToString("D11"))))));
    z.GetEntry("xl/worksheets/sheet1.xml").Delete();Add(z,"xl/worksheets/sheet1.xml",doc.ToString());
   }
   f=new Fake{Fn=w=>{if(!w.EndsWith("08"))throw new NoWaybill();return R(w);}};
   sum=new BatchRunner().Run(p,"Sheet1",0,5,f,new RunControl());Assert(f.Calls==8&&sum.Failed==7&&sum.Completed==1&&sum.Pending==0&&sum.Unreadable==7&&sum.Error==null,"more than five failures do not end batch");passed.Add("seven unreadable orders are marked and the eighth still completes; no batch failure-count limit");
   passed.AddRange(LayoutTests.Run());return new{Passed=passed.Count,Tests=passed,FixtureFolder=folder};
  }
  static string EntryText(ZipArchive zip,string name){using(var r=new StreamReader(zip.GetEntry(name).Open()))return r.ReadToEnd();}
 }
